//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			HE_Calibration fault                                                                                                                                                                                                                                                                 
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE				SIGN						DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0				2025-09-11		William Veim			Initial release
//	1.0.1				2025-11-21		William Veim			Set to false if not in use
//	1.2.0			    2026-07-06		William Veim			Rework logic
//	1.2.1				2026-07-07		Ruben Byman			Minor tweak to error calculation (now checking signal value as a percentage of ideal expected value)
//	1.2.2				2026-07-08		Ruben Byman			Bugfix to prevent all analog values to enter calibration fault simultaneously
//
//==============================================================================================================================
//
// 		FUNCTIONALITY:
// 		Calculate the expected signal value, based on calibration value and orginal scaling.
//
//==============================================================================================================================

//Calibration fault lower 
IF EXT_AnalogValue.EXT_Operator.Calibrate_Lower THEN
	
	SignalValue_Expected:=ScaleTrans(SclIn:=EXT_AnalogValue.EXT_Operator.CalibrateValue_Lower, X0:=EXT_AnalogValue.EXT_Engineering.ProcessValue_SensorMin, Y0:=SignalValue_X0, X1:=EXT_AnalogValue.EXT_Engineering.ProcessValue_SensorMax, Y1:=SignalValue_X1);

	CalibrationFault_Lower:=(HE_ABSValue(1-(EXT_AnalogValue.EXT_Engineering.SignalValue / SignalValue_Expected))*100) > EXT_AnalogValue.EXT_Engineering.Calibration_MaxDrift;
	
ELSE
	
	CalibrationFault_Lower:=FALSE;
	
END_IF;

//Calibration fault upper
IF EXT_AnalogValue.EXT_Operator.Calibrate_Upper THEN

	SignalValue_Expected:=ScaleTrans(SclIn:=EXT_AnalogValue.EXT_Operator.CalibrateValue_Upper, X0:=EXT_AnalogValue.EXT_Engineering.ProcessValue_SensorMin, Y0:=SignalValue_X0, X1:=EXT_AnalogValue.EXT_Engineering.ProcessValue_SensorMax, Y1:=SignalValue_X1);

	CalibrationFault_Upper:=(HE_ABSValue(1-(EXT_AnalogValue.EXT_Engineering.SignalValue / SignalValue_Expected))*100) > EXT_AnalogValue.EXT_Engineering.Calibration_MaxDrift;
	
ELSE
	
	CalibrationFault_Upper:=FALSE;
	
END_IF;
